/* Zcode — dados de Estudos II: guias, tabelas, linhas, formatos */

export const GUIAS = {
redacaoEstrutura: { nome: "Redação ENEM: Estrutura", chave: "red-estr",
sub: "O esqueleto da dissertação-argumentativa, competência por competência.",
secoes: [
{ t: "As 5 competências", h: "<p>A redação vale <b>1000 pontos</b>, 200 por competência. Decore o que cada uma cobra:</p><table><tr><th>Comp.</th><th>O que avalia</th></tr><tr><td><b>I</b></td><td>Domínio da norma culta: ortografia, concordância, regência, pontuação.</td></tr><tr><td><b>II</b></td><td>Compreender a proposta e aplicar repertório <b>produtivo</b> (que desenvolve o tema).</td></tr><tr><td><b>III</b></td><td>Argumentar com projeto de texto: tese clara, argumentos e coesão.</td></tr><tr><td><b>IV</b></td><td>Coesão: conectivos dentro e entre parágrafos, sem repetição.</td></tr><tr><td><b>V</b></td><td>Proposta de intervenção com <b>agente + ação + modo + efeito</b>, respeitando os direitos humanos.</td></tr></table>" },
{ t: "Introdução: tese + repertório", h: "<p>Em 5 a 7 linhas, apresente o tema, um repertório legitimador e a sua <b>tese</b> (opinião central).</p><ul><li><b>Contextualize:</b> dado, fato histórico ou citação que situe o problema.</li><li><b>Problematize:</b> mostre por que o tema é um desafio hoje.</li><li><b>Tese:</b> 1 frase com sua posição + prévia dos 2 argumentos (um por parágrafo de desenvolvimento).</li></ul><blockquote>Modelo: repertório → ligação com o tema → tese com 2 argumentos anunciados.</blockquote>" },
{ t: "Desenvolvimento: 2 parágrafos", h: "<p>Cada parágrafo desenvolve <b>um argumento</b> em 4 movimentos:</p><ol><li><b>Tópico frasal:</b> 1ª frase anuncia a ideia do parágrafo.</li><li><b>Repertório:</b> dado, citação, filme, lei ou fato histórico.</li><li><b>Análise:</b> explique COMO o repertório prova seu argumento (a parte mais importante).</li><li><b>Fechamento:</b> retome a tese com outras palavras.</li></ol><p>Sem análise, o repertório vira enfeite e a competência II despenca.</p>" },
{ t: "Conclusão: proposta completa", h: "<p>A proposta precisa de 5 elementos para nota máxima na competência V:</p><ul><li><b>Agente:</b> quem resolve (governo, escola, mídia, família, ONGs).</li><li><b>Ação:</b> o que será feito (verbo no infinitivo ou futuro).</li><li><b>Modo:</b> como será feito (por meio de…).</li><li><b>Efeito:</b> resultado esperado (a fim de…).</li><li><b>Detalhamento:</b> aprofunde UM dos elementos acima.</li></ul><p>Proposta que viola direitos humanos <b>zera a competência V</b>.</p>" },
{ t: "O que zera a redação", h: "<ul><li>Fuga total ao tema ou ao tipo dissertativo-argumentativo.</li><li>Texto com menos de <b>7 linhas</b> ou em branco.</li><li>Improperios, desenhos ou parte deliberadamente desconectada.</li><li>Assinatura, nome ou marca que identifique o autor.</li><li>Cópia integral dos textos motivadores.</li></ul><p>Escrever narração, poema ou carta no lugar da dissertação também zera.</p>" },
]},
redacaoRepertorio: { nome: "Redação ENEM: Repertório", chave: "red-rep",
sub: "Citações, leis e pensadores prontos para usar em qualquer tema.",
secoes: [
{ t: "Como usar (sem decorar à toa)", h: "<p>Repertório bom é <b>legitimado</b> (fonte confiável) e <b>pertinente</b> (ligado ao argumento). Regra de ouro:</p><ol><li>Apresente a fonte: <i>“Segundo o sociólogo Zygmunt Bauman…”</i>.</li><li>Contextualize: o que o autor disse e sobre o quê.</li><li>Problematize: ligue ao tema com <b>sua análise</b> — 2 a 3 linhas explicando a relação.</li></ol><p>Citação solta sem análise é repertório <b>decorativo</b>: não pontua na competência II.</p>" },
{ t: "Tecnologia e redes sociais", h: "<ul><li><b>Zygmunt Bauman</b> (modernidade líquida): relações frágeis e descartáveis — perfeito para temas de redes sociais e solidão.</li><li><b>Pierre Lévy</b> (cibercultura): a internet como espaço de inteligência coletiva — serve para educação digital e democracia online.</li><li><b>Marco Civil da Internet</b> (Lei 12.965/2014): garante neutralidade e privacidade — use em temas de dados e liberdade de expressão.</li><li><b>“O dilema das redes”</b> (documentário): algoritmos que moldam comportamento — ótimo para manipulação e saúde mental.</li></ul>" },
{ t: "Desigualdade e cidadania", h: "<ul><li><b>Constituição de 1988</b>, art. 6º: educação, saúde e moradia como direitos sociais — base para cobrar o Estado em qualquer tema social.</li><li><b>Sérgio Buarque de Holanda</b> (“homem cordial”): a informalidade que mistura público e privado — serve para corrupção e jeitinho.</li><li><b>Milton Santos</b>: o espaço reproduz desigualdades — ótimo para urbanização e acesso a serviços.</li><li><b>Paulo Freire</b>: educação como prática da liberdade — coringa para temas de ensino e emancipação.</li></ul>" },
{ t: "Meio ambiente", h: "<ul><li><b>Constituição, art. 225</b>: meio ambiente equilibrado como direito de todos e dever do poder público.</li><li><b>Relatório Brundtland</b>: desenvolvimento sustentável — atender o presente sem comprometer o futuro.</li><li><b>Acordo de Paris (2015)</b>: compromisso global de limitar o aquecimento — use em clima e energia.</li><li><b>Ailton Krenak</b> (“Ideias para adiar o fim do mundo”): crítica ao consumo predatório — forte para consumismo.</li></ul>" },
{ t: "Saúde, educação e comportamento", h: "<ul><li><b>SUS</b> (art. 196): saúde como direito universal — base para temas de saúde pública.</li><li><b>Émile Durkheim</b> (fato social e anomia): o coletivo molda o indivíduo — serve para pressão social, suicídio e desvio.</li><li><b>Michel Foucault</b> (vigiar e punir): disciplina e controle — ótimo para prisões, escolas e vigilância.</li><li><b>Simone de Beauvoir</b>: “ninguém nasce mulher, torna-se” — essencial para gênero e desigualdade.</li></ul>" },
]},
classesGramaticais: { nome: "Gramática: Classes de Palavras", chave: "cls-gram",
sub: "As 10 classes com função, exemplos e pegadinhas de prova.",
secoes: [
{ t: "Variáveis I: nome e companhia", h: "<table><tr><th>Classe</th><th>Função</th><th>Exemplo</th></tr><tr><td><b>Substantivo</b></td><td>Nomeia seres e coisas</td><td>casa, amor, Brasil</td></tr><tr><td><b>Adjetivo</b></td><td>Caracteriza o substantivo</td><td>casa <b>grande</b></td></tr><tr><td><b>Artigo</b></td><td>Determina o substantivo</td><td><b>o, a, um, uma</b></td></tr><tr><td><b>Numeral</b></td><td>Quantifica ou ordena</td><td><b>dois, terceiro, dobro</b></td></tr><tr><td><b>Pronome</b></td><td>Substitui ou acompanha o nome</td><td><b>eu, este, meu, que</b></td></tr></table><p>Variáveis = flexionam em gênero, número e (algumas) pessoa.</p>" },
{ t: "Variáveis II: o verbo", h: "<p>O verbo indica <b>ação, estado ou fenômeno</b> e flexiona em pessoa, número, tempo, modo e voz:</p><ul><li><b>Modo indicativo:</b> certeza (presente, pretérito perfeito/imperfeito/mais-que-perfeito, futuro do presente/pretérito).</li><li><b>Modo subjuntivo:</b> dúvida ou desejo (presente, pretérito imperfeito, futuro).</li><li><b>Modo imperativo:</b> ordem ou pedido (afirmativo e negativo).</li></ul><p>Formas nominais: <b>infinitivo</b> (cantar), <b>gerúndio</b> (cantando) e <b>particípio</b> (cantado).</p>" },
{ t: "Invariáveis: não flexionam", h: "<table><tr><th>Classe</th><th>Função</th><th>Exemplo</th></tr><tr><td><b>Advérbio</b></td><td>Modifica verbo, adjetivo ou advérbio</td><td>ontem, muito, aqui</td></tr><tr><td><b>Preposição</b></td><td>Liga palavras (regência)</td><td>de, em, para, com</td></tr><tr><td><b>Conjunção</b></td><td>Liga orações ou termos</td><td>e, mas, porque, se</td></tr><tr><td><b>Interjeição</b></td><td>Expressa emoção</td><td>ai! oba! nossa!</td></tr></table>" },
{ t: "Pegadinhas clássicas", h: "<ul><li><b>QUE:</b> pronome relativo (retoma termo: <i>o livro <b>que</b> li</i>) × conjunção (liga orações: <i>quero <b>que</b> venha</i>).</li><li><b>A:</b> artigo (<i><b>a</b> casa</i>) × preposição (<i>cheguei <b>a</b> casa</i>) × pronome (<i>vi-<b>a</b> ontem</i>).</li><li><b>Particípio × adjetivo:</b> <i>porta <b>aberta</b></i> (adjetivo, varia) × <i>tem <b>aberto</b></i> (particípio, invariável).</li><li><b>“Meio”:</b> advérbio = invariável (<i>elas estão <b>meio</b> cansadas</i>); numeral/adjetivo = varia (<i><b>meia</b> hora</i>).</li></ul>" },
]},
sintaxe: { nome: "Gramática: Sintaxe Essencial", chave: "sintaxe",
sub: "Termos da oração e período composto sem decoreba vazia.",
secoes: [
{ t: "Termos essenciais", h: "<ul><li><b>Sujeito:</b> de quem se fala. Tipos: simples, composto, oculto/desinencial, indeterminado, oração sem sujeito (haver existindo, fazer temporal, fenômenos).</li><li><b>Predicado:</b> o que se diz do sujeito. <b>Verbal</b> (verbo significativo), <b>nominal</b> (verbo de ligação + predicativo), <b>verbo-nominal</b> (os dois).</li><li><b>Verbos de ligação:</b> ser, estar, ficar, parecer, permanecer, continuar, andar, tornar-se, viver.</li></ul>" },
{ t: "Termos integrantes", h: "<p>Completam o sentido de verbos e nomes:</p><ul><li><b>Objeto direto:</b> completa verbo transitivo direto, sem preposição (<i>comprei <b>livros</b></i>).</li><li><b>Objeto indireto:</b> completa verbo transitivo indireto, com preposição (<i>gosto <b>de música</b></i>).</li><li><b>Complemento nominal:</b> completa nome (substantivo, adjetivo, advérbio) com preposição (<i>tenho medo <b>de altura</b></i>).</li><li><b>Agente da passiva:</b> quem pratica a ação na voz passiva (<i>feito <b>por ele</b></i>).</li><li><b>Predicativo:</b> caracteriza sujeito ou objeto (<i>ele chegou <b>cansado</b></i>).</li></ul>" },
{ t: "Termos acessórios", h: "<ul><li><b>Adjunto adnominal:</b> acompanha o substantivo (artigo, adjetivo, pronome, numeral, locução).</li><li><b>Adjunto adverbial:</b> indica circunstância (tempo, lugar, modo, causa…) — é o termo mais móvel da oração.</li><li><b>Aposto:</b> explica ou resume termo anterior (<i>Machado de Assis, <b>mestre do realismo</b>, escreveu…</i>).</li><li><b>Vocativo:</b> chama o interlocutor e <b>não</b> é termo da oração (<i><b>Maria</b>, venha cá</i>).</li></ul>" },
{ t: "Período composto", h: "<ul><li><b>Coordenação:</b> orações independentes. Aditivas (e), adversativas (mas), alternativas (ou…ou), conclusivas (logo), explicativas (porque = pois).</li><li><b>Subordinação:</b> oração dependente da principal. Substantivas (substitua por <b>ISSO</b>), adjetivas (com pronome relativo <b>que</b>) e adverbiais (causa, tempo, condição, concessão…).</li></ul><blockquote>Macete: se dá para trocar a oração por ISSO, é substantiva. Se tem QUE retomando um nome, é adjetiva.</blockquote>" },
]},
pontuacaoCrase: { nome: "Gramática: Pontuação e Crase", chave: "pont-crase",
sub: "Vírgula sem chute e crase com macete infalível.",
secoes: [
{ t: "Vírgula: 5 regras de ouro", h: "<ol><li><b>Enumeração:</b> separa itens de mesma função (<i>comprei pão, leite e café</i>).</li><li><b>Termo intercalado:</b> isola adjunto, aposto ou vocativo no meio (<i>os alunos, <b>atentos</b>, ouviram</i>).</li><li><b>Termo deslocado:</b> separa adjunto antecipado (<i><b>Ontem à noite</b>, choveu muito</i>).</li><li><b>Orações adversativas e explicativas:</b> antes de mas, pois, porque-explicação.</li><li><b>NUNCA</b> entre sujeito e predicado, nem entre verbo e objeto.</li></ol>" },
{ t: "Ponto e vírgula, dois-pontos e ponto", h: "<ul><li><b>Ponto e vírgula:</b> separa itens longos de enumeração e orações coordenadas extensas ou com vírgulas internas.</li><li><b>Dois-pontos:</b> anunciam enumeração, citação, explicação ou síntese.</li><li><b>Ponto final:</b> encerra período declarativo. <b>Reticências:</b> suspensão ou hesitação. <b>Travessão:</b> discurso direto ou destaque enfático.</li></ul>" },
{ t: "Crase: o macete", h: "<p>Crase = preposição <b>a</b> + artigo <b>a(s)</b>. Macete: troque por <b>AO</b>:</p><ul><li><i>Vou <b>à</b> praia</i> → “vou <b>ao</b> clube” (trocou por AO, tem crase).</li><li><i>Cheguei <b>a</b> casa cedo</i> → “cheguei ao lar”? Não faz sentido → sem crase.</li></ul><p><b>Proibida:</b> antes de verbo, de palavra repetida (<i>cara a cara</i>), de indefinidos (<i>alguma, toda</i> sem artigo), de “uma”, e depois de preposições (exceto <i>até a</i>).</p>" },
{ t: "Casos especiais", h: "<ul><li><b>Facultativa:</b> antes de nomes femininos próprios (<i>refiro-me <b>à/ a</b> Maria</i>), após <i>até</i> (<i>até <b>à/a</b> porta</i>) e antes de possessivas femininas singulares.</li><li><b>Horas determinadas:</b> <i>chegarei <b>às</b> 8h</i> (mas: <i>desde <b>as</b> 8h</i> — preposição “desde” bloqueia).</li><li><b>Locuções:</b> <i><b>à</b> noite, <b>à</b> direita, <b>à</b> venda, <b>à</b> medida que</i>.</li><li><b>“A” no singular + palavra no plural:</b> sem crase (<i>refiro-me <b>a</b> praias desertas</i>).</li></ul>" },
]},
literaturaAutores: { nome: "Literatura: Autores do Brasil", chave: "lit-aut",
sub: "Os 10 nomes que mais caem, com obra-chave e estilo de cada um.",
secoes: [
{ t: "Romantismo e Realismo", h: "<ul><li><b>José de Alencar</b> (romantismo): nacionalismo indianista — <i>O Guarani</i>, <i>Iracema</i>, <i>Senhora</i>.</li><li><b>Gonçalves Dias</b> (romantismo): poesia patriótica — “Canção do Exílio” (<i>“Minha terra tem palmeiras…”</i>).</li><li><b>Machado de Assis</b> (realismo): ironia e análise psicológica — <i>Dom Casmurro</i>, <i>Memórias Póstumas de Brás Cubas</i>, <i>Quincas Borba</i>.</li><li><b>Aluísio Azevedo</b> (naturalismo): determinismo do meio — <i>O Cortiço</i>.</li></ul>" },
{ t: "Poesia: do Parnasianismo ao Modernismo", h: "<ul><li><b>Olavo Bilac</b> (parnasianismo): forma perfeita, arte pela arte — “Ora (direis) ouvir estrelas”.</li><li><b>Carlos Drummond de Andrade</b> (modernismo 2ª fase): cotidiano e reflexão — “No meio do caminho”, “Mãos Dadas”, “Quadrilha”.</li><li><b>Cecília Meireles</b>: lirismo musical e efemeridade — <i>Romanceiro da Inconfidência</i>.</li><li><b>Vinicius de Moraes</b>: amor e samba — “Soneto de Fidelidade”, parceiro de Tom Jobim.</li></ul>" },
{ t: "Prosa moderna e regionalismo", h: "<ul><li><b>Graciliano Ramos</b> (regionalismo 2ª fase): seca e opressão, estilo seco — <i>Vidas Secas</i>, <i>São Bernardo</i>.</li><li><b>Guimarães Rosa</b>: linguagem inventiva do sertão — <i>Grande Sertão: Veredas</i> (Riobaldo e Diadorim).</li><li><b>Clarice Lispector</b>: introspecção e instante — <i>A Hora da Estrela</i> (Macabéa), <i>Laços de Família</i>.</li><li><b>Jorge Amado</b>: Bahia popular e mestiça — <i>Capitães da Areia</i>, <i>Dona Flor e Seus Dois Maridos</i>.</li></ul>" },
{ t: "Como a prova cobra", h: "<ul><li>ENEM foca em <b>interpretação de fragmentos</b>, não em decoreba de datas: leia o texto e identifique o estilo.</li><li>Marcas fortes: indianismo → Alencar; ironia machadiana → narrador em 1ª pessoa que duvida de tudo; seca → Graciliano; sertão inventivo → Rosa.</li><li>Fuvest/Unicamp pedem <b>leitura integral</b> das obras da lista — resumos não bastam para questões de detalhe.</li></ul>" },
]},
historiaColonia: { nome: "História: Colônia e Império", chave: "hist-col",
sub: "Do pau-brasil à Proclamação da República em 5 paradas.",
secoes: [
{ t: "Colônia: açúcar e escravidão", h: "<ul><li><b>Capitanias hereditárias</b> (1534) e Governo-Geral (1549, Salvador): ocupação e defesa do território.</li><li><b>Economia açucareira:</b> latifúndio, monocultura, escravidão africana e pacto colonial (exclusivo metropolitano).</li><li><b>Sociedade:</b> casa-grande e senzala — patriarcal, escravocrata e católica.</li><li><b>Mineração</b> (séc. XVIII): ouro em Minas, interiorização, <b>Derrama</b> e <b>Inconfidência Mineira</b> (1789, Tiradentes).</li></ul>" },
{ t: "Vinda da família real e Independência", h: "<ul><li><b>1808:</b> D. João VI foge de Napoleão; abertura dos portos e elevação a Reino Unido (1815).</li><li><b>1822:</b> D. Pedro I proclama a Independência (7 de setembro); mantém monarquia, escravidão e latifúndio.</li><li><b>1º Reinado</b> (1822–1831): Constituição de 1824 (Poder Moderador), autoritarismo e abdicação.</li><li><b>Regências</b> (1831–1840): revoltas (Cabanagem, Balaiada, Sabinada, Farroupilha) e Golpe da Maioridade.</li></ul>" },
{ t: "2º Reinado: café e crise", h: "<ul><li><b>Economia cafeeira</b> no Sudeste; fim do tráfico (Lei Eusébio de Queirós, 1850) e imigração europeia.</li><li><b>Guerra do Paraguai</b> (1864–1870): endividamento e fortalecimento do Exército abolicionista e republicano.</li><li><b>Leis abolicionistas:</b> Ventre Livre (1871), Sexagenários (1885) e <b>Áurea</b> (1888, Princesa Isabel).</li><li>Sem indenização nem reforma agrária: ex-escravizados à margem — raiz da desigualdade racial.</li></ul>" },
{ t: "Império em resumo de prova", h: "<table><tr><th>Data</th><th>Fato</th></tr><tr><td>1500–1530</td><td>Pau-brasil e feitorias (pré-colonização)</td></tr><tr><td>1534/1549</td><td>Capitanias / Governo-Geral</td></tr><tr><td>1808</td><td>Família real no Brasil</td></tr><tr><td>1822</td><td>Independência</td></tr><tr><td>1888/1889</td><td>Abolição / Proclamação da República</td></tr></table>" },
]},
historiaRepublica: { nome: "História: Brasil República", chave: "hist-rep",
sub: "De Deodoro à redemocratização: as fases que a prova adora.",
secoes: [
{ t: "República Velha (1889–1930)", h: "<ul><li><b>República da Espada</b> (Deodoro/Floriano) e depois <b>café com leite</b>: revezamento SP-MG.</li><li><b>Coronelismo, voto de cabresto</b> e política dos governadores: democracia de fachada.</li><li><b>Revoltas:</b> Canudos, Contestado, Vacina, tenentismo (Coluna Prestes).</li><li><b>1930:</b> crise do café (crash de 1929) + Revolução de 1930 → Getúlio Vargas.</li></ul>" },
{ t: "Era Vargas (1930–1945)", h: "<ul><li><b>Governo Provisório:</b> centralização, trabalhismo, criação do Ministério do Trabalho.</li><li><b>1932:</b> Revolução Constitucionalista (SP) e Constituição de 1934 (voto feminino).</li><li><b>Estado Novo</b> (1937–1945): ditadura, censura (DIP), CLT (1943), industrialização (CSN).</li><li>Brasil na <b>2ª Guerra</b> (FEB) e deposição de Vargas em 1945.</li></ul>" },
{ t: "Ditadura Militar (1964–1985)", h: "<ul><li><b>Golpe de 1964:</b> militares depõem João Goulart; Atos Institucionais (AI-5 em 1968: fecha Congresso, censura, prisões).</li><li><b>Milagre econômico</b> (1968–1973): crescimento com arrocho salarial e dívida externa.</li><li>Repressão: DOI-Codi, tortura, desaparecidos; resistência armada e cultural (Tropicália, imprensa alternativa).</li><li><b>Abertura:</b> Lei da Anistia (1979), Diretas Já (1984), fim em 1985 (Tancredo/Sarney).</li></ul>" },
{ t: "Nova República (1985–hoje)", h: "<ul><li><b>Constituição de 1988</b> (“cidadã”): direitos sociais, voto aos 16, SUS, eleições diretas.</li><li><b>Plano Real</b> (1994): fim da hiperinflação (FHC).</li><li>Alternância democrática: Lula (2003), Dilma (impeachment 2016), Temer, Bolsonaro, Lula III.</li><li>ENEM cobra: cidadania, movimentos sociais, Constituição e redemocratização.</li></ul>" },
]},
filosofiaAntiga: { nome: "Filosofia: Antiga e Medieval", chave: "fil-ant",
sub: "Dos pré-socráticos a Santo Agostinho: as bases do pensamento.",
secoes: [
{ t: "Pré-socráticos: a physis", h: "<ul><li>Primeiros a buscar explicação <b>racional</b> (logos) em vez de mítica para a natureza (<i>physis</i>).</li><li><b>Tales:</b> a água como princípio (<i>arché</i>). <b>Heráclito:</b> tudo flui (<i>panta rei</i>); o devir.</li><li><b>Parmênides:</b> o ser é uno e imutável — a mudança é ilusão dos sentidos.</li><li><b>Demócrito:</b> tudo é feito de <b>átomos</b> (materialismo antigo).</li></ul>" },
{ t: "Sócrates, Platão e Aristóteles", h: "<ul><li><b>Sócrates:</b> maiêutica (parto de ideias) e ironia; “só sei que nada sei”; ética e autoconhecimento.</li><li><b>Platão:</b> mundo das Ideias (essências perfeitas) × mundo sensível (cópia); <b>Mito da Caverna</b> (educação liberta); <i>A República</i> (rei-filósofo).</li><li><b>Aristóteles:</b> empirismo e lógica; 4 causas; ética da <b>mediania</b> (virtude entre excessos); homem como animal político.</li></ul>" },
{ t: "Helenismo: escolas práticas", h: "<ul><li><b>Estoicismo</b> (Zenão, Sêneca, Marco Aurélio): aceitar o destino, controlar as paixões; virtude basta para a felicidade.</li><li><b>Epicurismo</b> (Epicuro): prazer moderado e ausência de dor; amizade e vida simples.</li><li><b>Ceticismo:</b> suspender o juízo (<i>epoché</i>) diante da incerteza.</li><li><b>Cinismo</b> (Diógenes): desprezo às convenções, vida natural.</li></ul>" },
{ t: "Filosofia medieval: fé e razão", h: "<ul><li><b>Santo Agostinho:</b> une Platão ao cristianismo; tempo interior; mal como ausência do bem (<i>Confissões</i>).</li><li><b>São Tomás de Aquino:</b> une Aristóteles à fé; 5 vias para provar Deus (<i>Suma Teológica</i>); escolástica.</li><li>Questão central: conciliar <b>fé e razão</b> — a filosofia como “serva da teologia”.</li></ul>" },
]},
filosofiaModerna: { nome: "Filosofia: Moderna e Contemporânea", chave: "fil-mod",
sub: "Da dúvida metódica à sociedade do cansaço.",
secoes: [
{ t: "Racionalismo × Empirismo", h: "<ul><li><b>Descartes</b> (racionalismo): dúvida metódica; <i>“penso, logo existo”</i>; razão como fonte do saber.</li><li><b>Empiristas</b> (Locke, Hume): a mente é <i>tábula rasa</i>; todo conhecimento vem da <b>experiência</b>.</li><li><b>Kant</b> (criticismo): síntese — conhecimento nasce da experiência <b>organizada</b> pela razão; imperativo categórico na ética.</li></ul>" },
{ t: "Política moderna", h: "<ul><li><b>Maquiavel</b> (<i>O Príncipe</i>): separa política de moral; o poder tem lógica própria.</li><li><b>Hobbes</b> (<i>Leviatã</i>): estado de natureza = guerra de todos; contrato social com soberano absoluto.</li><li><b>Locke:</b> direitos naturais (vida, liberdade, propriedade); governo limitado e consentido.</li><li><b>Rousseau</b> (<i>Contrato Social</i>): soberania popular e vontade geral; desigualdade nasce da propriedade.</li><li><b>Montesquieu:</b> separação dos poderes (Executivo, Legislativo, Judiciário).</li></ul>" },
{ t: "Século XIX: crítica total", h: "<ul><li><b>Marx:</b> materialismo histórico; luta de classes como motor da história; mais-valia e alienação.</li><li><b>Nietzsche:</b> “Deus está morto”; crítica à moral do rebanho; vontade de potência e além-do-homem.</li><li><b>Comte</b> (positivismo): ordem e progresso; ciência como estágio final do saber — inspirou a bandeira do Brasil.</li></ul>" },
{ t: "Século XX e XXI", h: "<ul><li><b>Existencialismo</b> (Sartre): “a existência precede a essência” — somos condenados a ser livres.</li><li><b>Escola de Frankfurt</b> (Adorno): indústria cultural — a mídia padroniza consciências.</li><li><b>Foucault:</b> poder disciplinar (prisões, escolas, hospitais) e biopolítica.</li><li><b>Byung-Chul Han:</b> sociedade do desempenho e do cansaço — a autoexploração disfarçada de liberdade.</li></ul>" },
]},
biomas: { nome: "Biomas do Brasil", chave: "biomas",
sub: "Os 6 biomas: clima, vegetação e prova — com exemplos.",
secoes: [
{ t: "Amazônia e Mata Atlântica", h: "<ul><li><b>Amazônia</b> (~49% do país): floresta equatorial úmida, maior biodiversidade do planeta; “rios voadores” levam umidade ao Centro-Sul; ameaças: desmatamento e garimpo.</li><li><b>Mata Atlântica</b> (litoral): floresta tropical úmida riquíssima e a mais devastada (&lt;15% original); abriga as maiores cidades.</li></ul>" },
{ t: "Cerrado e Caatinga", h: "<ul><li><b>Cerrado</b>: savana de árvores tortas e gramíneas; “caixa-d'água do Brasil” (nascentes); fronteira do agronegócio.</li><li><b>Caatinga</b> (exclusiva do Brasil): vegetação xerófila adaptada à seca (mandacaru, juazeiro); sertão nordestino.</li></ul>" },
{ t: "Pampa e Pantanal", h: "<ul><li><b>Pampa</b> (RS): campos de gramíneas; pecuária e trigo; ameaçado pela arenização.</li><li><b>Pantanal</b>: maior planície alagável do mundo; cheia e vazante regulam a vida; santuário de jacarés, capivaras e onças.</li></ul>" },
{ t: "O que a prova cobra", h: "<ul><li>Associar bioma ↔ clima ↔ vegetação (ex.: Caatinga = semiárido = xerófila).</li><li>Impactos: desmatamento, queimadas, agronegócio × conservação; unidades de conservação e Código Florestal.</li><li>ENEM adora gráficos de desmatamento e textos sobre serviços ecossistêmicos (água, clima, polinização).</li></ul>" },
]},
quimicaEstequiometria: { nome: "Química: Estequiometria", chave: "qui-est",
sub: "Cálculos químicos passo a passo, do mol à reação.",
secoes: [
{ t: "Mol: a dúzia do químico", h: "<p><b>1 mol = 6,02 × 10²³ partículas</b> (Avogadro) e equivale à massa molar em gramas:</p><ul><li>H₂O: 2×1 + 16 = <b>18 g/mol</b>.</li><li>CO₂: 12 + 2×16 = <b>44 g/mol</b>.</li><li>Nas CNTP, 1 mol de gás ocupa <b>22,4 L</b>.</li></ul><p>Toda estequiometria é regra de três com a equação <b>balanceada</b>.</p>" },
{ t: "Balanceamento", h: "<p>Acertar os coeficientes para conservar átomos (Lavoisier). Método das tentativas:</p><ol><li>Comece pelo elemento que aparece <b>uma vez</b> em cada lado.</li><li>Deixe H e O por último.</li><li>Confira todos os átomos no final.</li></ol><p>Exemplo: CH₄ + 2 O₂ → CO₂ + 2 H₂O (C:1=1, H:4=4, O:4=4). ✓</p>" },
{ t: "Cálculo com reação (exemplo guiado)", h: "<p><b>Problema:</b> que massa de CO₂ se forma com 8 g de CH₄?</p><ol><li>Equação: CH₄ + 2 O₂ → CO₂ + 2 H₂O.</li><li>Mols: CH₄ = 16 g/mol → 8 g = <b>0,5 mol</b>.</li><li>Proporção 1:1 → 0,5 mol de CO₂.</li><li>Massa: 0,5 × 44 = <b>22 g de CO₂</b>.</li></ol>" },
{ t: "Rendimento e reagente limitante", h: "<ul><li><b>Reagente limitante:</b> o que acaba primeiro e determina quanto produto se forma — calcule mols de cada reagente e compare com a proporção.</li><li><b>Rendimento:</b> (obtido ÷ teórico) × 100. Se o teórico é 22 g e obteve 20 g → ~91%.</li><li><b>Pureza:</b> se o reagente tem 80% de pureza, multiplique a massa por 0,8 antes de converter.</li></ul>" },
]},
fisicaCinematica: { nome: "Física: Cinemática", chave: "fis-cin",
sub: "Movimento uniforme e variado: conceitos, fórmulas e quando usar.",
secoes: [
{ t: "Conceitos: referencial e velocidade", h: "<ul><li><b>Referencial:</b> movimento e repouso dependem do observador — passageiro parado no ônibus em movimento está em repouso <b>em relação ao ônibus</b>.</li><li><b>Velocidade média:</b> v = Δs ÷ Δt (ex.: 120 km em 2 h → 60 km/h).</li><li><b>Aceleração média:</b> a = Δv ÷ Δt — mede a variação da velocidade.</li><li>Conversão: <b>km/h → m/s divida por 3,6</b> (e multiplique no caminho inverso).</li></ul>" },
{ t: "MU: velocidade constante", h: "<p>No <b>Movimento Uniforme</b>, a = 0 e v é constante. Função horária:</p><blockquote><b>s = s₀ + v·t</b> (sorvete)</blockquote><p>Exemplo: carro a 20 m/s passa pelo km 10. Após 5 s: s = 10 + 20×5 = <b>110 m</b>.</p><p>Gráfico s×t é reta; v×t é reta horizontal; encontro de móveis: iguale as funções.</p>" },
{ t: "MUV: aceleração constante", h: "<ul><li><b>v = v₀ + a·t</b> (vovô ateu)</li><li><b>s = s₀ + v₀·t + a·t²/2</b> (sorvetão)</li><li><b>v² = v₀² + 2·a·Δs</b> (Torricelli — use quando <b>não</b> há tempo)</li></ul><p>Queda livre: MUV com a = g ≈ 10 m/s²; no ponto mais alto do lançamento vertical, v = 0.</p>" },
{ t: "Como escolher a fórmula", h: "<table><tr><th>Dados</th><th>Use</th></tr><tr><td>Sem aceleração</td><td>s = s₀ + v·t</td></tr><tr><td>Tem tempo, quer velocidade</td><td>v = v₀ + a·t</td></tr><tr><td>Tem tempo, quer posição</td><td>s = s₀ + v₀·t + a·t²/2</td></tr><tr><td>Sem tempo</td><td>v² = v₀² + 2·a·Δs</td></tr></table>" },
]},
};

